#include <iostream>
#include <cmath>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long cnt = 0;

    for (long long a = 1; a <= n; ++a) {
        for (long long b = a + 1; b <= n; ++b) {
            long long sum = a * a + b * b;
            long long c = static_cast<long long>(sqrt(static_cast<long double>(sum)));

            while ((c + 1) * (c + 1) <= sum) ++c;
            while (c * c > sum) --c;

            if (c <= n && c * c == sum) {
                ++cnt;
            }
        }
    }

    cout << cnt << '\n';
    return 0;
}

